"""Privacy configuration authored in ``agent.yml`` for Mantle deployments."""

from __future__ import annotations

from typing import Any, Mapping, Optional

from pydantic import ValidationError as PydanticValidationError

from rasa.exceptions import ValidationError
from rasa.privacy.privacy_config import TrackerStoreSettings
from rasa.shared.exceptions import RasaException

PRIVACY_KEY = "privacy"
RULES_KEY = "rules"
TRACKER_STORE_SETTINGS_KEY = "tracker_store_settings"
_MANTLE_PRIVACY_KEYS = frozenset({TRACKER_STORE_SETTINGS_KEY})
_TRACKER_STORE_POLICY_KEYS = frozenset({"deletion", "anonymization"})


def mantle_privacy_rules_rejected_message() -> str:
    """Explain that Mantle anonymization lives on memory fields, not ``rules``."""
    return (
        "Mantle agent.yml does not accept a privacy 'rules' block. "
        "Set anonymization on a memory field that has pii: true."
    )


def extract_privacy_mapping(
    config_data: Optional[Mapping[str, Any]],
) -> Optional[dict[str, Any]]:
    """Return the ``privacy`` block from a top-level ``agent.yml`` mapping.

    Raises:
        ValidationError: When ``privacy`` is present but not a mapping.
    """
    if config_data is None or PRIVACY_KEY not in config_data:
        return None

    raw = config_data[PRIVACY_KEY]
    if raw is None:
        return None
    if not isinstance(raw, Mapping):
        raise ValidationError(
            code="config.agent.invalid_privacy_section",
            event_info=(
                f"Invalid agent configuration: '{PRIVACY_KEY}' must be a YAML mapping."
            ),
        )
    return dict(raw)


def tracker_store_settings_from_privacy(
    privacy: Mapping[str, Any],
) -> Optional[TrackerStoreSettings]:
    """Return tracker-store cron settings, rejecting keys Mantle does not read.

    ``rules`` is rejected: anonymization methods belong on ``pii: true`` memory
    fields. Tracker-store cron settings stay in this block.

    Raises:
        RasaException: When the block contains ``rules``, another unknown key,
            or invalid tracker-store settings.
    """
    unknown = set(privacy) - _MANTLE_PRIVACY_KEYS
    if RULES_KEY in unknown:
        raise RasaException(mantle_privacy_rules_rejected_message())
    if unknown:
        names = ", ".join(sorted(unknown))
        raise RasaException(
            f"Mantle agent.yml privacy only accepts '{TRACKER_STORE_SETTINGS_KEY}'. "
            f"Unexpected keys: {names}."
        )

    raw_settings = privacy.get(TRACKER_STORE_SETTINGS_KEY)
    if not raw_settings:
        return None
    if not isinstance(raw_settings, Mapping):
        raise RasaException(
            f"'{TRACKER_STORE_SETTINGS_KEY}' in agent.yml privacy must be a mapping."
        )
    unknown_settings = set(raw_settings) - _TRACKER_STORE_POLICY_KEYS
    if unknown_settings:
        names = ", ".join(sorted(unknown_settings))
        raise RasaException(
            f"'{TRACKER_STORE_SETTINGS_KEY}' in agent.yml only accepts "
            f"'deletion' and 'anonymization'. Unexpected keys: {names}."
        )
    return TrackerStoreSettings.from_dict(dict(raw_settings))


def validate_agent_privacy_section(
    config_data: Mapping[str, Any],
) -> Optional[str]:
    """Validate ``privacy`` when present; return a human-readable error or ``None``."""
    try:
        privacy = extract_privacy_mapping(config_data)
    except ValidationError as error:
        return str(error.info or error)

    if privacy is None:
        return None

    try:
        tracker_store_settings_from_privacy(privacy)
    except (
        RasaException,
        ValidationError,
        PydanticValidationError,
        TypeError,
    ) as error:
        if isinstance(error, PydanticValidationError):
            return str(error)
        return str(getattr(error, "info", None) or error)
    return None
